-- Generated by medallion from spec/tables/gold_daily_revenue.toml. Do not edit by hand.
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.gold.daily_revenue (
  order_date DATE COMMENT 'Day the order was placed (UTC)',
  country STRING COMMENT 'Customer country; ZZ when the customer is unknown',
  orders_count BIGINT COMMENT 'Completed orders',
  revenue DECIMAL(18,2) COMMENT 'Sum of order totals',
  avg_order_value DECIMAL(18,2) COMMENT 'Average order total'
)
COMMENT 'Completed-order revenue by day and customer country, for finance and sales reporting.'
TBLPROPERTIES (
  'governance.owner' = 'sales-data',
  'governance.domain' = 'sales',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/gold_daily_revenue.toml',
  'governance.grain' = 'order_date, country'
)
AS SELECT
  CAST(to_date(o.order_ts) AS DATE) AS order_date,
  CAST(coalesce(c.country, 'ZZ') AS STRING) AS country,
  CAST(count(*) AS BIGINT) AS orders_count,
  CAST(sum(o.amount) AS DECIMAL(18,2)) AS revenue,
  CAST(round(avg(o.amount), 2) AS DECIMAL(18,2)) AS avg_order_value
FROM ${catalog}.silver.orders AS o
LEFT JOIN ${catalog}.silver.customers AS c ON o.customer_id = c.customer_id AND c.__END_AT IS NULL
WHERE o.status = 'completed'
GROUP BY to_date(o.order_ts), coalesce(c.country, 'ZZ');
